style.css:
@-moz-document domain("roblox.com") {
body {
        background: url("https://imgur.com/a/5ssZ9iX") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Masque les éléments gênants pour un fond propre */
    .navigation-container, .navbar, .footer, .game-cards {
        background: transparent !important;
    }

    /* Texte en blanc pour contraster avec le fond sombre */
    * {
        color: white !important;
    }
}
